from rdkit import Chem
from rdkit.Chem import AllChem, rdDistGeom
import numpy as np

rw=Chem.RWMol()
def atom(sym):
 a=Chem.Atom(sym)
 if sym in ('Ru','Sn','P'): a.SetNoImplicit(True)
 return rw.AddAtom(a)
def bond(i,j,bt=Chem.BondType.SINGLE): rw.AddBond(i,j,bt)
def phenyl(p):
 ids=[atom('C') for _ in range(6)]
 for i in ids:rw.GetAtomWithIdx(i).SetIsAromatic(True)
 for i in range(6):bond(ids[i],ids[(i+1)%6],Chem.BondType.AROMATIC)
 bond(p,ids[0]);return ids
ru=atom('Ru'); pu=atom('P');pd=atom('P');px=atom('P');sn=atom('Sn')
for p in [pu,pd,px]:bond(p,ru,Chem.BondType.DATIVE)
bond(ru,sn)
u=phenyl(pu);bond(u[1],sn)
d=phenyl(pd);bond(d[1],ru)
rings=[u,d]
for p,n in [(pu,2),(pd,2),(px,3)]:
 for k in range(n):rings.append(phenyl(p))
me=[atom('C'),atom('C')]
for c in me:bond(c,sn)
m=rw.GetMol();Chem.SanitizeMol(m);m=Chem.AddHs(m)
print('atoms',m.GetNumAtoms(),'formula',Chem.rdMolDescriptors.CalcMolFormula(m))
print('smiles',Chem.MolToSmiles(m))
print('keys',ru,pu,pd,px,sn,u,d,me)
ps=AllChem.ETKDGv3();ps.randomSeed=209;ps.useRandomCoords=True;ps.maxIterations=3000
print('embedding',AllChem.EmbedMolecule(m,ps))
ff=AllChem.UFFGetMoleculeForceField(m)
print('ff',ff is not None)
for a,b,L in [(ru,pu,2.34),(ru,pd,2.34),(ru,px,2.38),(ru,sn,2.64),(ru,d[1],2.08)]:
 ff.UFFAddDistanceConstraint(a,b,False,L,L,1500)
# Control coordination arrangement while allowing distortions.
for a,b,angle,tol,k in [(pu,pd,168,6,300),(pu,sn,83,4,150),(pd,d[1],70,3,200),(sn,px,120,10,80),(px,d[1],120,10,80),(sn,d[1],120,10,80),(pu,px,94,8,60),(pd,px,94,8,60)]:
 ff.UFFAddAngleConstraint(a,ru,b,False,angle-tol,angle+tol,k)
# Force phosphorus and tin tetrahedral angles with the metal bond; maintain trigonal aryl C.
for p in [pu,pd,px]:
 for nbr in m.GetAtomWithIdx(p).GetNeighbors():
  if nbr.GetIdx()!=ru:ff.UFFAddAngleConstraint(ru,p,nbr.GetIdx(),False,105,116,120)
for n in m.GetAtomWithIdx(sn).GetNeighbors():
 if n.GetIdx()!=ru:ff.UFFAddAngleConstraint(ru,sn,n.GetIdx(),False,102,116,120)
for n in m.GetAtomWithIdx(d[1]).GetNeighbors():
 if n.GetIdx()!=ru:ff.UFFAddAngleConstraint(ru,d[1],n.GetIdx(),False,115,126,150)
# Ru lies near aryl plane (C-C-C-Ru).
ff.UFFAddTorsionConstraint(d[3],d[2],d[1],ru,False,175,185,50)
ff.Initialize()
print('start energy',ff.CalcEnergy())
for it in range(8):
 res=ff.Minimize(maxIts=2500)
 print(it,res,ff.CalcEnergy())
 if not res:break
Chem.MolToMolFile(m,'intermediate.mol')
np.save('xyz0.npy',np.array(m.GetConformer().GetPositions()))
